// Padroniza os itens do Google News, tira repetidos da mesma rodada
// e ignora o que tem mais de 24h.
const vistos = new Set();
const agora = Date.now();
const saida = [];
for (const item of $input.all()) {
  const j = item.json;
  const guid = j.guid || j.link;
  if (!guid || vistos.has(guid)) continue;
  vistos.add(guid);
  const quando = new Date(j.isoDate || j.pubDate || 0).getTime();
  if (!quando || agora - quando > 24 * 3600 * 1000) continue;
  // Google News: "Manchete - Veiculo"
  const titulo = (j.title || '').trim();
  const corte = titulo.lastIndexOf(' - ');
  const manchete = corte > 0 ? titulo.slice(0, corte).trim() : titulo;
  const veiculo = corte > 0 ? titulo.slice(corte + 3).trim() : 'Fonte';
  // corte rapido de opiniao antes de gastar IA
  if (/^(opini[aã]o|coluna|editorial|artigo)\b/i.test(manchete)) continue;
  saida.push({ json: {
    guid, busca: j.busca, manchete, veiculo,
    link: j.link, publicado_em: new Date(quando).toISOString()
  }});
}
return saida;

// Le a resposta da IA e decide o que vira linha no banco.
const respostas = $input.all();
const originais = $('Remover ja vistas').all();
const saida = [];
for (let i = 0; i < respostas.length; i++) {
  const o = originais[i].json;
  let r;
  try {
    const bruto = (respostas[i].json.content || [])
      .filter(c => c.type === 'text').map(c => c.text).join('');
    const achado = bruto.match(/\{[\s\S]*\}/);   // pega so o JSON, ignora texto em volta
    r = JSON.parse(achado ? achado[0] : bruto);
  } catch (e) {
    continue; // resposta quebrada: ignora
  }
  if (r.descartar) continue;
  if (!['13', '22', 'ambos'].includes(r.lado)) continue;
  if (!['noticia', 'pesquisa', 'agenda'].includes(r.tipo)) continue;
  // pesquisa so entra com registro no TSE
  if (r.tipo === 'pesquisa' && !r.registro_tse) continue;
  saida.push({ json: {
    id_externo: o.guid,
    lado: r.lado,
    tipo: r.tipo,
    veiculo: o.veiculo,
    manchete: o.manchete,
    resumo: (r.resumo || '').slice(0, 220),
    link: o.link,
    publicado_em: o.publicado_em,
    instituto: r.instituto || null,
    registro_tse: r.registro_tse || null,
    status: 'pendente'
  }});
}
return saida;
